    "business": "Java / Spring Boot / Spring Cloud / MyBatis / MySQL",
    "agent": "Python + Flask; bounded manual tool loop",
    "rag": "pgvector + PostgreSQL; Markdown/TXT/PDF/OCR/complex tables; citations/version/ACL/evaluation",
    "cache": "Redis",
    "events": "RocketMQ expiry checks + Kafka facts + Outbox",
    "documents": "MongoDB parsed blocks / sessions / run traces",
    "delivery": "Docker / local K8s / CI/CD",
    "performance": "JUC / JVM / database tuning",
    "write_boundary": "confirmed proposal -> Java reauthorization + idempotent local transaction; simulated payment, no real refund"
  },
