    await page.locator('.detail-content .detail-sku').getByText('COURSE-001', {exact:true}).waitFor();
    result.injectedUiCases.push('注入详情404，三语详情错误和重试按钮翻译，重试恢复真实详情');

    const firstDetailStarted = deferred();
    const lateDetail = deferred();
    const lateHandled = deferred();
    await page.route('**/api/v1/products/1', async route => {
      const actualResponse = await route.fetch();
      firstDetailStarted.resolve();
      await lateDetail.promise;
      try {
        await route.fulfill({response:actualResponse});
        lateHandled.resolve(null);
      } catch (error) {
        lateHandled.resolve(error);
      }
    });
    const firstAborted = page.waitForEvent('requestfailed', {predicate:request => new URL(request.url()).pathname === '/api/v1/products/1'});
    await page.locator('.detail-button').first().click();
    await firstDetailStarted.promise;
    await page.locator('.detail-button').nth(1).click();
    await page.locator('.detail-content .detail-sku').getByText('TOOL-002', {exact:true}).waitFor();
    await firstAborted;
    lateDetail.resolve();
    const lateError = await lateHandled.promise;
    // Some browser versions reject fulfilling an already-cancelled routed request.
    if (lateError) assert.ok((await firstAborted).failure(), 'late fulfilment only fails for the cancelled request');
    await page.unroute('**/api/v1/products/1');
    assert.equal(await page.locator('.detail-content .detail-sku').innerText(), 'TOOL-002');
    assert.equal(await page.locator('.detail-error').count(), 0);
    result.realChain.push('延迟真实商品1响应后立即选择商品2：旧请求被取消，无错误提示，详情保持商品2');

    const invalid = await browser.newPage({viewport:{width:1440,height:960}});
    listen(invalid);
    await invalid.addInitScript(key => localStorage.setItem(key, 'en-US'), storageKey);
    await invalid.goto(base);
    await rows(invalid);
    assert.equal(await invalid.locator('#language-select').inputValue(), 'zh-CN');
    assert.equal(await invalid.title(), translate('zh-CN', 'appTitle'));
    result.storageCases.push('无效已保存语言 en-US 回退中文');
    await invalid.close();

    const blocked = await browser.newPage({viewport:{width:1440,height:960}});
    listen(blocked);
    await blocked.addInitScript(() => Object.defineProperty(window,'localStorage',{
      configurable:true,get(){throw new DOMException('blocked for test','SecurityError')},
    }));
    await blocked.goto(base);
    await rows(blocked);
    await localeOf(blocked, 'en');
    assert.equal(await blocked.locator('tbody tr').count(), 3);
    result.storageCases.push('注入localStorage访问失败，页面正常加载并可切换英文');
    await blocked.close();

    const mobile = await browser.newPage({viewport:{width:390,height:844},isMobile:true,deviceScaleFactor:1});
    listen(mobile);
    await mobile.goto(base);
    await rows(mobile);
    for (const locale of locales) {
      await localeOf(mobile, locale);
      await mobile.locator('.detail-button').nth(2).click();
      await mobile.locator('.detail-content .detail-sku').getByText('GUIDE-003', {exact:true}).waitFor();
      assert.equal(await mobile.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1), true, `${locale} mobile overflow`);
      assert.equal(await mobile.locator('tbody .price').first().innerText(), '¥129.90');
      await screenshot(mobile, `step-02-i18n-mobile-${locale}`);
      result.realChain.push(`${locale}: 390px真实列表与零库存详情，无整页水平溢出，人民币金额未转换`);
    }
    assert.equal(result.pageErrors.length, 0);
    result.passed = true;
  } catch (error) {
    result.passed = false;
    result.failure = error.stack || String(error);
    throw error;
  } finally {
    fs.writeFileSync(path.join(root, 'evidence/step-02-i18n-browser.json'), JSON.stringify(result,null,2));
    await browser.close();
  }
  console.log(JSON.stringify(result));
})().catch(error => {console.error(error);process.exitCode=1});

// Browser spot-check: real offline HTML, no mocked map data.
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright');

(async () => {
  const root = path.resolve(__dirname, '..');
  const step = process.argv[2] || 'step-01';
  const browser = await chromium.launch({headless: true,
    executablePath: process.env.CHROME_PATH || 'C:/Program Files/Google/Chrome/Application/chrome.exe'});
  try {
    const page = await browser.newPage({viewport:{width:1440,height:960}});
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.goto(pathToFileURL(path.join(root, 'docs/mindmaps', `${step}.html`)).href);
    await page.locator('.node-group').first().waitFor();
    await page.locator('#expand-all').click();
    await page.waitForTimeout(350);
    const positions = await page.locator('.node-group').evaluateAll(nodes => nodes.map(n => n.getAttribute('transform')));
    if (positions.length < 10 || new Set(positions).size < 10) throw new Error('Expanded nodes overlap or missing');
    let mvcXml = false;
    let requestValidation = false;
    let i18n = false;
    let frontendOnlyI18n = false;
    if (step === 'step-02') {
      await page.locator('[data-id="java-productserviceimpl"]').click();
      if (!(await page.locator('#detail-content').innerText()).includes('ProductServiceImpl')) throw new Error('MVC implementation missing');
      await page.locator('[data-id="mapper-xml"]').click();
      const xmlDetail = await page.locator('#detail-content').innerText();
      if (!xmlDetail.includes('ProductMapper.xml') || !xmlDetail.includes('namespace')) throw new Error('XML source preview missing');
      mvcXml = true;
      await page.locator('[data-id="http-adapter"]').click();
      const requestDetail = await page.locator('#detail-content').innerText();
      if (!requestDetail.includes('response.text()') || !requestDetail.includes('validate')) throw new Error('Updated getJson preview missing');
      await page.locator('[data-id="http-validation"]').click();
      if (!(await page.locator('#detail-content').innerText()).includes('value is Product')) throw new Error('Runtime type guard preview missing');
      requestValidation = true;
      await page.locator('[data-id="i18n-set-locale"]').click();
      const localeDetail = await page.locator('#detail-content').innerText();
      if (!localeDetail.includes('setLocale') || !localeDetail.includes('localStorage')) throw new Error('Locale source preview missing');
      await page.locator('[data-id="i18n-translate"]').click();
      if (!(await page.locator('#detail-content').innerText()).includes('messages[locale][key]')) throw new Error('Dictionary interpolation preview missing');
      await page.locator('[data-id="i18n-error"]').click();
      if (!(await page.locator('#detail-content').innerText()).includes('error.apiCode')) throw new Error('Translated error source preview missing');
      await page.locator('[data-id="development-context"]').click();
      if (!(await page.locator('#detail-content').innerText()).includes('DEVELOPMENT-CONTEXT.md')) throw new Error('New-dialog context preview missing');
      i18n = true;
      if (await page.locator('[data-id="error-locale-resolver"]').count()) throw new Error('Removed backend locale resolver still appears as implemented');
      await page.locator('[data-id="backend-error-code"]').click();
      const backendError = await page.locator('#detail-content').innerText();
      if (!backendError.includes('new ApiError') || backendError.includes('messages.getMessage')) throw new Error('Fixed backend code/message preview missing');
      await page.locator('[data-id="http-language-independent"]').click();
      const apiLanguage = await page.locator('#detail-content').innerText();
      if (!apiLanguage.includes("Accept: 'application/json'") || apiLanguage.includes('useI18n().locale.value')) throw new Error('API language separation preview missing');
      frontendOnlyI18n = true;
    }
    await page.locator('[data-id="complete"]').click();
    if (!(await page.locator('#detail-content').innerText()).includes('complete')) throw new Error('Code detail not updated');
    await page.locator('#search-input').fill('SQLite');
    await page.waitForTimeout(250);
    if (!(await page.locator('#detail-content').innerText()).includes('SQLite')) throw new Error('Search did not find SQLite');
    await page.locator('#search-input').fill('xyz-no-match-000');
    await page.waitForTimeout(250);
    const noMatchText = await page.locator('#detail-content').innerText();
    if (noMatchText.includes('SQLite 学习台账')) throw new Error('Search results were not cleared');
    await page.locator('#search-input').fill('');
    await page.locator('#expand-all').click();
    await page.locator('#zoom-fit').click();
    await page.screenshot({path:path.join(root, 'evidence', `${step}-mindmap.png`)});
    if (errors.length) throw new Error(errors.join('; '));
    const report = {passed:true, mode:'browser spot-check', source:'offline self-contained HTML',
      expandedNodes:positions.length, uniquePositions:new Set(positions).size,
      detail:true, search:true, clearNoMatch:true, zoom:true, mvcXml, requestValidation, i18n, frontendOnlyI18n, pageErrors:errors};
    fs.writeFileSync(path.join(root,'evidence',`${step}-map-browser.json`), JSON.stringify(report,null,2));
    console.log(JSON.stringify(report));
  } finally { await browser.close(); }
})().catch(e => {console.error(e);process.exitCode=1});

