.brand svg { width: 29px; height: 29px; color: var(--accent); }
.header-caption { color: var(--muted); font-size: 13px; }
.header-actions { display: flex; align-items: center; gap: 20px; }
.language-switcher select { min-height: 40px; max-width: 136px; padding: 8px 28px 8px 12px; border: 1px solid #b8c8c0; border-radius: 6px; color: #253d35; background: #fff; font-size: 16px; cursor: pointer; }
main { max-width: 1384px; padding: 42px 32px 24px; margin: 0 auto; }
main:focus { outline: none; }
.page-heading { display: flex; justify-content: space-between; align-items: center; gap: 24px; margin-bottom: 30px; }
.page-heading > div { min-width: 0; }
.page-heading p { color: var(--muted); font-size: 14px; line-height: 1.7; margin-top: 7px; }
.button { display: inline-flex; justify-content: center; align-items: center; gap: 7px; min-height: 40px; padding: 9px 15px; border-radius: 6px; border: 1px solid transparent; font-size: 13px; font-weight: 600; line-height: 1.4; transition: background-color 160ms ease-out; }
.secondary { color: #304c40; background: #fff; border-color: #bdcec5; }
.secondary:hover:not(:disabled) { background: #edf3ef; }
.primary { color: #fff; background: var(--accent); }
.primary:hover:not(:disabled) { background: #104b39; }
.button:active:not(:disabled) { background: #dcebe2; color: #174e3c; }
.workspace { display: grid; grid-template-columns: minmax(0, 1fr) 306px; gap: 24px; align-items: start; }
.catalog, .detail-panel { background: #fff; border: 1px solid var(--line); border-radius: 12px; overflow: hidden; }
.catalog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 24px; border-bottom: 1px solid var(--line); }
.count { font-size: 12px; line-height: 1.5; color: var(--muted); margin-top: 4px; }
